                if actual_output >= edge.capacity - 0.01:
                    return (
                        LimitingFactor.BELT_CAPACITY,
                        f"Output belt {out_edge.id} at capacity ({edge.capacity}/min)",
                    )
                # Otherwise, downstream doesn't need more
